/** Public URL of a file in a public Supabase Storage bucket. */
export function photoUrl(path: string, bucket = "review-photos"): string {
  const base = process.env.NEXT_PUBLIC_SUPABASE_URL ?? "";
  return `${base}/storage/v1/object/public/${bucket}/${path.split("/").map(encodeURIComponent).join("/")}`;
}

export const PHOTO_TYPES: Record<string, string> = { "image/jpeg": "jpg", "image/png": "png", "image/webp": "webp" };
export const MAX_REVIEW_PHOTOS = 4;
export const MAX_PHOTO_BYTES = 5 * 1024 * 1024;

/** A path the user may attach: inside their own folder, generated by the upload widget. */
export function isOwnPhotoPath(path: string, userId: string): boolean {
  return new RegExp(`^${userId}/[a-z0-9-]{8,64}\\.(jpg|png|webp)$`).test(path);
}
